const e="Course Registration",t={verified:!1,lastEdited:"9/9/2026",branch:"main",tablesPresent:0,tablesConsumed:0,tablesOnPage:0,tablesExcluded:0,sourceUrl:"https://catalog.northeastern.edu/graduate/engineering/academic-policies-procedures/course-registration-withdrawal/",panes:[""],planOfStudyCourses:[],verification:{level:"partial",kind:"grad",score:.83,checkedAt:"2026-09-10",sourceUrl:"https://catalog.northeastern.edu/graduate/engineering/academic-policies-procedures/course-registration-withdrawal/",sourcesAvailable:["requirement-tables","course-catalog"],counters:{tablesUnaccounted:0,leakedMarkers:0,unenumeratedSections:1,duplicateSectionTitles:0,duplicateConcentrationTitles:0,zeroTotal:1,unknownCourses:0,planUnexplained:0,impossibleSections:0},discrepancies:[{check:"missing-total-credits",severity:"medium",message:"the catalog page states no total credit requirement",detail:[{key:"noTotal"}],overflow:0},{check:"unenumerated-sections",severity:"info",message:"1 section(s) state a credit requirement whose courses the catalog does not list, so completion of those cannot be checked automatically",detail:[{key:"unenumeratedSection",params:{title:"2026-2027 Edition",sh:8}}],overflow:0}]}},r=0,s=2027,o=[{type:"SECTION",title:"2026-2027 Edition",creditsRequired:8,minRequirementCount:1,requirements:[],notes:["Full-time students (domestic and international) in the Graduate School of Engineering must register for classes on an ongoing basis and carry a minimum of 8 semester hours of coursework per semester. Any student who is appointed to a stipended graduate assistantship is considered full time for the term(s) of appointment if enrolled for a minimum of 6 semester hours.","All graduate students who are registered for Dissertation Term 1, Dissertation Term 2, Dissertation Continuation, PhD Candidacy Preparation, PhD Exam Preparation, or a 0-semester-hour Research course are considered full time. Registration in these courses is restricted to students who qualify for registration in these courses.","The graduate school does not require part-time students to be enrolled for a certain minimum number of semester hours in any term. However, part-time students who are not enrolled for more than one term (excluding summer terms) should take a leave of absence from Northeastern University to maintain active student status to keep their student account active.","The maximum number of semester hours approved for a student in each term varies by the degree program. However, a student can petition their faculty advisor to request permission to register for more than the allowed maximum number of semester hours for a given term. Normally, no more than 12 semester hours (inclusive of transfer credits and advanced standing for MS programs) may be taken outside the College of Engineering, unless otherwise specified in the program requirements.","Registration in classes is mandatory to maintain an active status with the university. Students must be registered in all courses for a given term prior to the university course add/drop deadline. Students should not register for an excessive number of courses or for multiple sections of the same course with the intention of dropping half or more of the courses during the first week of classes.","Students must be registered in their last semester of study. International students should consult with the Office of Global Services if they are intending to complete their program during the summer semester. Domestic students finishing their requirements in the summer semester must be registered either in summer session A, summer session B, or summer term.","Any student who is financially withdrawn by Student Accounts prior to the start of any given semester will not be permitted to register for that semester until they rectify the outstanding financial obligation.","The Graduate School of Engineering will correct registration errors. Corrections may generate a new tuition bill.","Due to last-minute scheduling changes, the Graduate School of Engineering must occasionally substitute faculty or change class schedules after the registration period has begun. Any student registered for the original course will automatically be registered for the updated section should no major schedule conflicts be apparent. Otherwise, the graduate school or the department will contact all affected students for alternatives.","Northeastern reserves the right to cancel, postpone, combine, or modify any class.","The Graduate School of Engineering does not allow College of Engineering graduate students to elect a satisfactory/unsatisfactory grading scheme for courses normally letter graded."]}],i={name:e,metadata:t,totalCreditsRequired:r,yearVersion:s,requirementSections:o};export{i as default,t as metadata,e as name,o as requirementSections,r as totalCreditsRequired,s as yearVersion};
